import { useEffect, useState } from "react";
import api from "./api"; // axios instance

export default function CodeEditorPage() {
  const userId = localStorage.getItem("userId"); // 🔑 logged user
  const [language, setLanguage] = useState("python");
  const [code, setCode] = useState("");
  const [fontSize, setFontSize] = useState(16);

  const [levels, setLevels] = useState([]);
  const [currentLevel, setCurrentLevel] = useState(null);
  const [level, setLevel] = useState(null);

  /* ================= LOAD LEVEL LIST ================= */
  useEffect(() => {
    async function loadLevels() {
      try {
        const res = await api.get(`/levels/${userId}`);
        setLevels(res.data.levels);
        setCurrentLevel(res.data.currentLevel);
      } catch (err) {
        console.error("Level list error", err);
      }
    }
    loadLevels();
  }, [userId]);

  /* ================= LOAD CURRENT LEVEL ================= */
  useEffect(() => {
    if (!currentLevel) return;

    async function loadCurrentLevel() {
      try {
        const res = await api.get(`/level/${userId}`);
        setLevel(res.data.level);
      } catch (err) {
        console.error("Current level error", err);
      }
    }
    loadCurrentLevel();
  }, [currentLevel, userId]);

  if (!level) return <h2 style={{ color: "white" }}>Loading...</h2>;

  return (
    <div style={styles.app}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.logo}>DailyCode</h1>
        <div style={styles.controls}>
          <select
            style={styles.choice}
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
          >
            <option value="python">Python</option>
            <option value="javascript">JavaScript</option>
            <option value="c">C</option>
            <option value="cpp">C++</option>
            <option value="java">Java</option>
          </select>
          <div>
            <button style={styles.fontBtn} onClick={() => setFontSize(fontSize + 2)}>A+</button>
            <button style={styles.fontBtn} onClick={() => setFontSize(fontSize - 2)}>A-</button>
          </div>
        </div>
      </div>

      {/* BODY */}
      <div style={styles.body}>
        {/* LEVEL SIDEBAR */}
        <div style={styles.sidebar}>
          <h3>Levels</h3>
          {levels.map((l) => (
            <button
              key={l.level_no}
              style={{
                ...styles.levelBtn,
                ...(l.level_no === currentLevel
                  ? styles.current
                  : l.level_no < currentLevel
                  ? styles.completed
                  : styles.locked),
              }}
              disabled={l.level_no > currentLevel}
            >
              Level {l.level_no}
            </button>
          ))}
        </div>

        {/* MAIN */}
        <div style={styles.main}>
          <h2 style={styles.levelTitle}>
            Level {level.level_no}: {level.title}
          </h2>
          <p style={styles.description}>{level.description}</p>

          {/* EDITOR */}
          <textarea
            value={code}
            onChange={(e) => setCode(e.target.value)}
            placeholder={`Write your ${language} code here...`}
            style={{
              width: "100%",
              height: "300px",
              background: "#0f172a",
              color: "#f1f5f9",
              border: "1px solid #334155",
              borderRadius: "8px",
              padding: "10px",
              fontSize: fontSize,
              fontFamily: "monospace",
            }}
          />

          {/* ACTIONS */}
          <div style={styles.actions}>
            <button style={styles.runBtn}>▶ Run</button>
            <button style={styles.submitBtn}>✔ Submit</button>
          </div>

          {/* INPUT / OUTPUT */}
          <div style={styles.outputs}>
            <div style={styles.expected}>
              <h4>Expected Output</h4>
              <pre>{level.expected_output}</pre>
            </div>
            <div style={styles.actual}>
              <h4>Your Output</h4>
              <pre>/* Output will show here */</pre>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ================= INLINE STYLES ================= */
const styles = {
  app: {
    background: "#0f172a",
    color: "#f1f5f9",
    minHeight: "100vh",
    fontFamily: "Inter, sans-serif",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    background: "#1e293b",
    padding: "10px 20px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.4)",
  },
  logo: { fontSize: "1.5rem", fontWeight: "bold", color: "#38bdf8" },
  controls: { display: "flex", gap: "15px", alignItems: "center" },
  choice: { padding: "6px", borderRadius: "6px", border: "none" },
  fontBtn: {
    marginLeft: "5px",
    padding: "6px 10px",
    borderRadius: "6px",
    border: "none",
    background: "#334155",
    color: "#f1f5f9",
    cursor: "pointer",
  },
  body: { display: "flex", padding: 20, gap: 20 },
  sidebar: { width: 200 },
  levelBtn: {
    display: "block",
    width: "100%",
    marginBottom: 8,
    padding: 10,
    borderRadius: 6,
    border: "none",
    cursor: "pointer",
    fontWeight: "bold",
  },
  current: { background: "#4caf50", color: "white" },
  completed: { background: "#2196f3", color: "white" },
  locked: { background: "#475569", color: "#cbd5e1", cursor: "not-allowed" },
  main: { flex: 1, background: "#1e293b", padding: 20, borderRadius: 10 },
  levelTitle: { color: "#38bdf8" },
  description: { marginBottom: 15 },
  editorBox: { border: "1px solid #334155", borderRadius: 8, overflow: "hidden" },
  actions: { marginTop: 10 },
  runBtn: {
    padding: "8px 16px",
    borderRadius: 6,
    border: "none",
    cursor: "pointer",
    fontWeight: "bold",
    background: "#3b82f6",
    color: "white",
  },
  submitBtn: {
    padding: "8px 16px",
    borderRadius: 6,
    border: "none",
    cursor: "pointer",
    fontWeight: "bold",
    background: "#4caf50",
    color: "white",
    marginLeft: 10,
  },
  sampleInput: { marginTop: 15 },
  userInput: {
    width: "100%",
    height: 60,
    borderRadius: 6,
    padding: 8,
    background: "#0f172a",
    color: "#f1f5f9",
    border: "1px solid #334155",
  },
  outputs: { display: "flex", gap: 20, marginTop: 20 },
  expected: {
    flex: 1,
    background: "#334155",
    padding: 10,
    borderRadius: 6,
    color: "#f1f5f9",
  },
  actual: {
    flex: 1,
    background: "#334155",
    padding: 10,
    borderRadius: 6,
    color: "#f1f5f9",
  },
};
